package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** A member to add: a pool, a person or another pool, and a share percent (at most two decimals, more than 0.00, at most 100.00), and
 * the membership's from-date and to-date (each optional; a to-date before the from-date is refused). */
public class ValidatePoolMember {

    private static final Pattern SHARE = Pattern.compile("\\d+(\\.\\d{1,2})?");

    private static final BigDecimal HUNDRED = new BigDecimal("100.00");

    public void validate(@RequestBody PoolMemberRequest request, Out<PoolMemberInput> member, Out<ChangedBy> changedBy)
            throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        if (request == null || request.pool() == null || request.pool().isBlank()) {
            throw new BadRequestException("Choose a pool");
        }
        String memberPool = request.memberPool() == null ? "" : request.memberPool().trim();
        if (request.person() == null && memberPool.isEmpty()) {
            throw new BadRequestException("Choose a person or a pool");
        }
        String text = request.share() == null ? "" : request.share().trim();
        if (!SHARE.matcher(text).matches()) {
            throw new BadRequestException("A share is a percent with at most two decimals");
        }
        BigDecimal share = new BigDecimal(text).setScale(2);
        if (share.signum() <= 0 || share.compareTo(HUNDRED) > 0) {
            throw new BadRequestException("A share is more than 0.00 and at most 100.00");
        }
        LocalDate from = date(request.from());
        LocalDate to = date(request.to());
        if (from != null && to != null && to.isBefore(from)) {
            throw new BadRequestException("A membership's to-date cannot be before its from-date");
        }
        member.set(new PoolMemberInput(request.pool().trim(), request.person(),
                request.person() == null ? memberPool : null, share, from, to));
        changedBy.set(by);
    }

    private static LocalDate date(String value) throws BadRequestException {
        String date = value == null ? "" : value.trim();
        if (date.isEmpty()) {
            return null;
        }
        try {
            return LocalDate.parse(date);
        } catch (DateTimeParseException e) {
            throw new BadRequestException("Enter a date as YYYY-MM-DD");
        }
    }
}
-- The sheet's pools: a name (stored trimmed, at most once on its sheet: the app refuses a repeat with a message, the
-- index is the backstop) and its members, each a person of the sheet at most once in the pool with a share percent
-- (two decimals, more than 0.00 and at most 100.00). A person can be in several pools.
CREATE TABLE pool (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL
);
CREATE UNIQUE INDEX pool_sheet_name ON pool (sheet_id, name);

CREATE TABLE pool_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    pool_id   BIGINT       NOT NULL REFERENCES pool (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    share     DECIMAL(5, 2) NOT NULL
);
CREATE UNIQUE INDEX pool_member_pool_person ON pool_member (pool_id, person_id);

-- Snapshotted with the rest of the screen (see V40, V41).
CREATE TABLE hist.pool AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM pool t WHERE FALSE;
CREATE INDEX hist_pool_snapshot ON hist.pool (snapshot_id);
CREATE TABLE asof.pool AS SELECT * FROM pool WHERE FALSE;
CREATE TABLE hist.pool_member AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM pool_member t WHERE FALSE;
CREATE INDEX hist_pool_member_snapshot ON hist.pool_member (snapshot_id);
CREATE TABLE asof.pool_member AS SELECT * FROM pool_member WHERE FALSE;
-- A pool member may be another pool of the sheet instead of a person: exactly one of person_id and member_pool_id is
-- set. A pool is a member of at most one pool, never of itself through any chain, and a chain of pools is at most
-- three deep (the app refuses each with a message). A member pool has no pot of its own: its pot is its cut in the
-- pool above.
ALTER TABLE pool_member ALTER COLUMN person_id SET NULL;
ALTER TABLE pool_member ADD COLUMN member_pool_id BIGINT REFERENCES pool (id);
CREATE UNIQUE INDEX pool_member_member_pool ON pool_member (member_pool_id);
-- The sheet's snapshots, and their layout as of a date, carry it too.
ALTER TABLE hist.pool_member ALTER COLUMN pers

