74	/**
75	 * Adds the person, or another pool, to the pool with its share. A person already in the pool is refused; so is a pool
76	 * that is the pool itself or contains it through any chain, a pool already a member of a pool, and one that would make
77	 * a chain of pools more than {@link PoolRepository#MAX_DEPTH} deep.
78	 */
79	public class AddPoolMember {
80	    public void add(@Val SheetResponse sheet, @Val PoolMemberInput input, PoolRepository pools, PersonRepository people,
81	            Out<PoolMemberAdded> added) throws BadRequestException {
82	        Long poolId = pools.findId(sheet.id(), input.pool());
83	        if (poolId == null) {
84	            throw new BadRequestException("No such pool on this sheet");
85	        }
86	        if (input.personId() == null) {
87	            Long memberId = pools.findId(sheet.id(), input.memberPool());
88	            if (memberId == null) {
89	                throw new BadRequestException("No such pool on this sheet");
90	            }
91	            if (pools.chainUp(poolId).contains(memberId)) {
92	                throw new BadRequestException("A pool cannot contain itself");
93	            }
94	            if (pools.parentOf(memberId) != null) {
95	                throw new BadRequestException(input.memberPool() + " is already a member of a pool");
96	            }
97	            if (pools.chainUp(poolId).size() + pools.height(memberId) > PoolRepository.MAX_DEPTH) {
98	                throw new BadRequestException("A chain of pools is at most " + PoolRepository.MAX_DEPTH + " deep");
99	            }
100	            if (!pools.addPoolMember(sheet.id(), poolId, memberId, input.share(), input.from(), input.to())) {
101	                throw new BadRequestException(input.memberPool() + " is already a member of a pool");
102	            }
103	            added.set(new PoolMemberAdded(sheet.id(), input.pool(), input.memberPool(), input.share(),
104	                    input.from(), input.to()));
105	            return;
106	        }
107	        Person person = people.find(sheet.id(), input.personId());
108	        if (person == null) {
109	            throw new BadRequestException("No such person on this sheet");
110	        }
111	        if (!pools.addMember(sheet.id(), poolId, person.getId(), input.share(), input.from(), input.to())) {
112	            throw new BadRequestException(person.getName() + " is already in this pool");
113	        }
114	        added.set(new PoolMemberAdded(sheet.id(), input.pool(), person.getName(), input.share(),
115	                input.from(), input.to()));
116	    }
117	}
