174	package net.officefloor.hq.app.pool;
175	
176	import java.math.BigDecimal;
177	import java.math.RoundingMode;
178	import java.time.LocalDate;
179	import java.util.ArrayList;
180	import java.util.HashMap;
181	import java.util.HashSet;
182	import java.util.LinkedHashMap;
183	import java.util.List;
184	import java.util.Map;
185	import java.util.Set;
186	import net.officefloor.hq.app.access.Setting;
187	import net.officefloor.hq.app.access.SettingRepository;
188	import net.officefloor.hq.app.sheet.SheetRepository;
189	import org.springframework.jdbc.core.JdbcTemplate;
190	import org.springframework.stereotype.Repository;
191	
192	/**
193	 * The pools of each sheet, in the order added, each name at most once on its sheet, and their members: people, and
194	 * other pools (each a member of at most one pool, never of itself through any chain, chains at most three deep).
195	 */
196	@Repository
197	public class PoolRepository {
198	
199	    /** The most pools a chain of pools holds, the top one included. */
200	    public static final int MAX_DEPTH = 3;
201	
202	    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
203	
204	    private final JdbcTemplate jdbc;
205	
206	    public PoolRepository(JdbcTemplate jdbc) {
207	        this.jdbc = jdbc;
208	    }
209	
210	    /** The id of the sheet's pool of that name; null when there is none. */
211	    public Long findId(String sheetId, String name) {
212	        return jdbc.query("SELECT id FROM pool WHERE sheet_id = ? AND name = ?", (rs, n) -> rs.getLong(1), sheetId, name)
213	                .stream().findFirst().orElse(null);
214	    }
215	
216	    public void insert(String sheetId, String name) {
217	        jdbc.update("INSERT INTO pool (sheet_id, name) VALUES (?, ?)", sheetId, name);
218	    }
219	
220	    /** Adds the person to the pool, with the membership's dates (each null when not given); false when they are in it already. */
221	    public boolean addMember(String sheetId, long poolId, long personId, BigDecimal share, LocalDate from, LocalDate to) {
222	        return jdbc.update("INSERT INTO pool_member (sheet_id, pool_id, person_id, share, from_date, to_date)"
223	                + " SELECT ?, ?, ?, ?, ?, ? WHERE NOT EXISTS (SELECT 1 FROM pool_member WHERE pool_id = ? AND person_id = ?)",
224	                sheetId, poolId, personId, share, sqlDate(from), sqlDate(to), poolId, personId) > 0;
225	    }
226	
227	    /** Adds the other pool to the pool, with the membership's dates; false when it is a member of a pool already. */
228	    public boolean addPoolMember(String sheetId, long poolId, long memberPoolId, BigDecimal share, LocalDate from,
229	            LocalDate to) {
230	        return jdbc.update("INSERT INTO pool_member (sheet_id, pool_id, member_pool_id, share, from_date, to_date)"
231	                + " SELECT ?, ?, ?, ?, ?, ? WHERE NOT EXISTS (SELECT 1 FROM pool_member WHERE member_pool_id = ?)",
232	                sheetId, poolId, memberPoolId, share, sqlDate(from), sqlDate(to), memberPoolId) > 0;
233	    }
234	
235	    private static java.sql.Date sqlDate(LocalDate date) {
236	        return date == null ? null : java.sql.Date.valueOf(date);
237	    }
238	
239	    /** The id of the pool the pool is a member of; null when none. */
240	    public Long parentOf(long poolId) {
241	        return jdbc.query("SELECT pool_id FROM pool_member WHERE member_pool_id = ?", (rs, n) -> rs.getLong(1), poolId)
242	                .stream().findFirst().orElse(null);
243	    }
244	
245	    /** The pool and the pools above it, the pool first. */
246	    public List<Long> chainUp(long poolId) {
247	        List<Long> chain = new ArrayList<>();
248	        for (Long id = poolId; id != null && !chain.contains(id); id = parentOf(id)) {
249	            chain.add(id);
250	        }
251	        return chain;
252	    }
253	
254	    /** How many pools deep the pool's longest chain down runs, the pool itself counting 1. */
255	    public int height(long poolId) {
256	        return height(poolId, 0);
257	    }
258	
259	    private int height(long poolId, int guard) {
260	        if (guard > MAX_DEPTH) {
261	            return guard;
262	        }
263	        int below = 0;
264	        for (Long child : jdbc.queryForList("SELECT member_pool_id FROM pool_member WHERE pool_id = ?"
265	                + " AND member_pool_id IS NOT NULL", Long.class, poolId)) {
266	            below = Math.max(below, height(child, guard + 1));
267	        }
268	        return 1 + below;
269	    }
270	
271	    /**
272	     * The sheet's pools, in the order added, each with its members in the order added, the total of their shares (a
273	     * retired member's share counted as given) and whether it is exactly 100.00. A member
274	     * whose membership dates do not include the sheet's today is left out entirely: not in the total share, nor the
275	     * balance, and no cut (not even 0.00). A pool that is a member of none has the sheet's pot; a member pool's pot is
276	     * its cut in the pool above (none while that has no cuts). Each member of a balanced pool with a pot has a cut: 0.00
277	     * when retired or held (a hold in force on the sheet's today), else the pot times their share over the shares of
278	     * the members with a cut added up, half to even to two decimals, and the remainder to the member with the smallest
279	     * non-zero cut (the latest added on a tie; the last member with a share when no cut is non-zero), so the cuts total the pot. A hold or a retirement leaves the pool's
280	     * total share and balance as they are. A pool whose every member (in its dates) is retired has no cuts.
281	     */
282	    public List<PoolResponse> list(String sheetId) {
283	        Map<Long, String> names = new LinkedHashMap<>();
284	        Map<Long, List<PoolResponse.Member>> members = new LinkedHashMap<>();
285	        Map<Long, List<Long>> memberPools = new HashMap<>();
286	        Map<Long, Long> parents = new HashMap<>();
287	        jdbc.query("SELECT id, name FROM pool WHERE sheet_id = ? ORDER BY id", rs -> {
288	            names.put(rs.getLong("id"), rs.getString("name"));
289	            members.put(rs.getLong("id"), new ArrayList<>());
290	            memberPools.put(rs.getLong("id"), new ArrayList<>());
291	        }, sheetId);
292	        Set<Long> held = new HashSet<>(jdbc.queryForList("SELECT DISTINCT h.person_id FROM person_hold h"
293	                + " JOIN person p ON p.id = h.person_id WHERE p.sheet_id = ? AND (h.from_date IS NULL OR h.from_date <= ?)"
294	                + " AND (h.to_date IS NULL OR h.to_date >= ?)", Long.class, sheetId, today(sheetId), today(sheetId)));
295	        java.sql.Date today = today(sheetId);
296	        jdbc.query("SELECT m.pool_id, m.person_id, m.member_pool_id, m.share, m.from_date, m.to_date, p.name,"
297	                + " p.retired_from, q.name AS pool_name"
298	                + " FROM pool_member m LEFT JOIN person p ON p.id = m.person_id LEFT JOIN pool q ON q.id = m.member_pool_id"
299	                + " WHERE m.sheet_id = ? ORDER BY m.id", rs -> {
300	            long poolId = rs.getLong("pool_id");
301	            List<PoolResponse.Member> of = members.get(poolId);
302	            if (of == null) {
303	                return;
304	            }
305	            String share = rs.getBigDecimal("share").setScale(2).toPlainString();
306	            java.sql.Date from = rs.getDate("from_date");
307	            java.sql.Date to = rs.getDate("to_date");
308	            boolean out = (from != null && from.after(today)) || (to != null && to.before(today));
309	            long memberPoolId = rs.getLong("member_pool_id");
310	            if (rs.wasNull()) {
311	                long personId = rs.getLong("person_id");
312	                of.add(new PoolResponse.Member(personId, null, rs.getString("name"), share,
313	                        rs.getDate("retired_from") != null, held.contains(personId), out, null));
314	                memberPools.get(poolId).add(null);
315	            } else {
316	                String name = rs.getString("pool_name");
317	                of.add(new PoolResponse.Member(null, name, name, share, false, false, out, null));
318	                memberPools.get(poolId).add(memberPoolId);
319	                parents.put(memberPoolId, poolId);
320	            }
321	        }, sheetId);
322	        String potValue = new SettingRepository(jdbc).find(sheetId, Setting.POT);
323	        BigDecimal pot = potValue == null ? null : new BigDecimal(potValue);
324	        Map<Long, String> totals = new HashMap<>();
325	        Map<Long, Boolean> balanced = new HashMap<>();
326	        names.keySet().forEach(id -> {
327	            BigDecimal total = BigDecimal.ZERO.setScale(2);
328	            for (PoolResponse.Member m : members.get(id)) {
329	                if (!m.out()) {
330	                    total = total.add(new BigDecimal(m.share()));
331	                }
332	            }
333	            totals.put(id, total.toPlainString());
334	            balanced.put(id, total.compareTo(HUNDRED) == 0);
335	        });
336	        Map<Long, List<PoolResponse.Member>> cutOf = new HashMap<>();
337	        names.keySet().forEach(id -> cuts(id, pot, parents, members, memberPools, balanced, cutOf, 0));
338	        List<PoolResponse> pools = new ArrayList<>();
339	        names.forEach((id, name) -> pools.add(new PoolResponse(name, cutOf.get(id), totals.get(id), balanced.get(id))));
340	        return pools;
341	    }
342	
343	    private java.sql.Date today(String sheetId) {
344	        return java.sql.Date.valueOf(new SheetRepository(jdbc).today(sheetId));
345	    }
346	
347	    /** The pool's members with their cuts of its pot, worked out (and kept in {@code cutOf}) above it first. */
348	    private static List<PoolResponse.Member> cuts(long id, BigDecimal sheetPot, Map<Long, Long> parents,
349	            Map<Long, List<PoolResponse.Member>> members, Map<Long, List<Long>> memberPools, Map<Long, Boolean> balanced,
350	            Map<Long, List<PoolResponse.Member>> cutOf, int depth) {
351	        List<PoolResponse.Member> done = cutOf.get(id);
352	        if (done != null) {
353	            return done;
354	        }
355	        BigDecimal pot = sheetPot;
356	        Long parent = parents.get(id);
357	        if (parent != null) {
358	            pot = null;
359	            if (depth <= MAX_DEPTH) {
360	                List<PoolResponse.Member> above = cuts(parent, sheetPot, parents, members, memberPools, balanced, cutOf,
361	                        depth + 1);
362	                int at = memberPools.get(parent).indexOf(id);
363	                String cut = at < 0 ? null : above.get(at).cut();
364	                pot = cut == null ? null : new BigDecimal(cut);
365	            }
366	        }
367	        List<PoolResponse.Member> of = balanced.get(id) && pot != null && !allRetired(members.get(id))
368	                ? cut(members.get(id), pot) : members.get(id);
369	        cutOf.put(id, of);
370	        return of;
371	    }
372	
373	    /** Whether the pool has members in their dates and every one of them is retired. */
374	    private static boolean allRetired(List<PoolResponse.Member> members) {
375	        boolean any = false;
376	        for (PoolResponse.Member m : members) {
377	            if (!m.out()) {
378	                if (!m.retired()) {
379	                    return false;
380	                }
381	                any = true;
382	            }
383	        }
384	        return any;
385	    }
386	
387	    /**
388	     * The members with their cuts of the pot, spread over the members with a cut (neither retired, held nor out of their dates) by their
389	     * shares; the remainder goes to the smallest non-zero cut among them, the latest added on a tie (to the last of them
390	     * with a share when none has a non-zero cut).
391	     */
392	    private static List<PoolResponse.Member> cut(List<PoolResponse.Member> members, BigDecimal pot) {
393	        BigDecimal shares = BigDecimal.ZERO.setScale(2);
394	        for (PoolResponse.Member m : members) {
395	            if (m.hasCut()) {
396	                shares = shares.add(new BigDecimal(m.share()));
397	            }
398	        }
399	        List<BigDecimal> cuts = new ArrayList<>();
400	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
401	        int smallest = -1;
402	        int last = -1;
403	        for (int i = 0; i < members.size(); i++) {
404	            PoolResponse.Member m = members.get(i);
405	            BigDecimal cut = !m.hasCut() || shares.signum() == 0 ? BigDecimal.ZERO.setScale(2)
406	                    : pot.multiply(new BigDecimal(m.share())).divide(shares, 2, RoundingMode.HALF_EVEN);
407	            cuts.add(cut);
408	            sum = sum.add(cut);
409	            if (m.hasCut() && new BigDecimal(m.share()).signum() > 0) {
410	                last = i;
411	            }
412	            if (m.hasCut() && cut.signum() != 0 && (smallest < 0 || cut.compareTo(cuts.get(smallest)) <= 0)) {
413	                smallest = i;
414	            }
415	        }
416	        int to = smallest >= 0 ? smallest : last;
417	        if (to >= 0 && shares.signum() != 0) {
418	            cuts.set(to, cuts.get(to).add(pot.subtract(sum)));
419	        }
420	        List<PoolResponse.Member> cut = new ArrayList<>();
421	        for (int i = 0; i < members.size(); i++) {
422	            PoolResponse.Member m = members.get(i);
423	            cut.add(m.out() ? m : m.withCut(cuts.get(i).setScale(2).toPlainString()));
424	        }
425	        return cut;
426	    }
427	}
