559	/** A member to add: a pool, a person or another pool, and a share percent (at most two decimals, more than 0.00, at most 100.00), and
560	 * the membership's from-date and to-date (each optional; a to-date before the from-date is refused). */
561	public class ValidatePoolMember {
562	
563	    private static final Pattern SHARE = Pattern.compile("\\d+(\\.\\d{1,2})?");
564	
565	    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
566	
567	    public void validate(@RequestBody PoolMemberRequest request, Out<PoolMemberInput> member, Out<ChangedBy> changedBy)
568	            throws BadRequestException {
569	        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
570	        if (request == null || request.pool() == null || request.pool().isBlank()) {
571	            throw new BadRequestException("Choose a pool");
572	        }
573	        String memberPool = request.memberPool() == null ? "" : request.memberPool().trim();
574	        if (request.person() == null && memberPool.isEmpty()) {
575	            throw new BadRequestException("Choose a person or a pool");
576	        }
577	        String text = request.share() == null ? "" : request.share().trim();
578	        if (!SHARE.matcher(text).matches()) {
579	            throw new BadRequestException("A share is a percent with at most two decimals");
580	        }
581	        BigDecimal share = new BigDecimal(text).setScale(2);
582	        if (share.signum() <= 0 || share.compareTo(HUNDRED) > 0) {
583	            throw new BadRequestException("A share is more than 0.00 and at most 100.00");
584	        }
585	        LocalDate from = date(request.from());
586	        LocalDate to = date(request.to());
587	        if (from != null && to != null && to.isBefore(from)) {
588	            throw new BadRequestException("A membership's to-date cannot be before its from-date");
589	        }
590	        member.set(new PoolMemberInput(request.pool().trim(), request.person(),
591	                request.person() == null ? memberPool : null, share, from, to));
592	        changedBy.set(by);
593	    }
594	
595	    private static LocalDate date(String value) throws BadRequestException {
596	        String date = value == null ? "" : value.trim();
597	        if (date.isEmpty()) {
598	            return null;
599	        }
600	        try {
601	            return LocalDate.parse(date);
602	        } catch (DateTimeParseException e) {
603	            throw new BadRequestException("Enter a date as YYYY-MM-DD");
604	        }
605	    }
606	}
607	-- The sheet's pools: a name (stored trimmed, at most once on its sheet: the app refuses a repeat with a message, the
608	-- index is the backstop) and its members, each a person of the sheet at most once in the pool with a share percent
609	-- (two decimals, more than 0.00 and at most 100.00). A person can be in several pools.
610	CREATE TABLE pool (
611	    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
612	    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
613	    name     VARCHAR(200) NOT NULL
614	);
615	CREATE UNIQUE INDEX pool_sheet_name ON pool (sheet_id, name);
616	
617	CREATE TABLE pool_member (
618	    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
619	    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
620	    pool_id   BIGINT       NOT NULL REFERENCES pool (id),
621	    person_id BIGINT       NOT NULL REFERENCES person (id),
622	    share     DECIMAL(5, 2) NOT NULL
623	);
624	CREATE UNIQUE INDEX pool_member_pool_person ON pool_member (pool_id, person_id);
