626	-- Snapshotted with the rest of the screen (see V40, V41).
627	CREATE TABLE hist.pool AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM pool t WHERE FALSE;
628	CREATE INDEX hist_pool_snapshot ON hist.pool (snapshot_id);
629	CREATE TABLE asof.pool AS SELECT * FROM pool WHERE FALSE;
630	CREATE TABLE hist.pool_member AS SELECT t.*, CAST(NULL AS BIGINT) AS snapshot_id FROM pool_member t WHERE FALSE;
